query TypeDump($name:String!){
  __type(name:$name){
    name
    kind
    description
    fields(includeDeprecated:true){
      name
      description
      args{
        name
        description
        defaultValue
        type{ kind name ofType{ kind name ofType{ kind name ofType{ kind name ofType{ kind name }}}}}
      }
      type{ kind name ofType{ kind name ofType{ kind name ofType{ kind name ofType{ kind name }}}}}
      isDeprecated
      deprecationReason
    }
    inputFields{
      name
      description
      defaultValue
      type{ kind name ofType{ kind name ofType{ kind name ofType{ kind name ofType{ kind name }}}}}
    }
    enumValues(includeDeprecated:true){
      name
      description
      isDeprecated
      deprecationReason
    }
    possibleTypes{ name kind }
  }
}
